"""QQ-白模参考：一个节点里挑姿态 / 脸模 / 服装三类参考图。

三路独立输出，各自接到需要的地方（ControlNet 预处理、图生图参考等）。
某个类型选「未使用」时该路输出阻塞，下游分支直接跳过，不会拿空值硬跑。

图片全部放在用户目录（见 ``guli_pose_db``），插件目录只放代码；
画廊由前端 ``web/qq_guli_pose_gallery.js`` 提供，点击类型才展开看大图。
"""

from __future__ import annotations

from typing import Any

try:  # 包内导入（ComfyUI 正常加载）
    from . import guli_pose_db as db
except ImportError:  # pragma: no cover - 测试里按独立模块加载
    import guli_pose_db as db  # type: ignore[no-redef]

try:
    from comfy_execution.graph import ExecutionBlocker
except Exception:  # pragma: no cover
    ExecutionBlocker = None

UNUSED = db.UNUSED


def _blocker() -> Any:
    return ExecutionBlocker(None) if ExecutionBlocker is not None else None


def _choices(lib: str) -> list[str]:
    """下拉选项：未使用 + 该库所有条目。库读不出来也只有「未使用」。"""
    try:
        return db.labels(lib)
    except Exception:  # 库坏了也不能让节点注册失败
        return [UNUSED]


def _pick_one(lib: str, selection: Any) -> Any:
    """取一路的 IMAGE；未使用或库里没有这条就返回阻塞。"""
    label = str(selection or "").strip()
    if not label or label == UNUSED:
        return _blocker()
    try:
        item = db.find(lib, label)
    except Exception:
        item = None
    if item is None:
        return _blocker()
    try:
        path, _angle = db.resolve(lib, item)
        return db.load_pixels(path)
    except Exception as err:  # 图坏了：让下游明确停下，而不是塞个空图
        print(f"[QQ-白模参考] 读取失败（{lib}/{label}）：{err}", flush=True)
        return _blocker()


class QQGuliPosePicker:
    CATEGORY = "QQ/图库"
    FUNCTION = "pick"
    RETURN_TYPES = ("IMAGE", "IMAGE", "IMAGE")
    RETURN_NAMES = ("姿态图", "脸模图", "服装图")
    DESCRIPTION = (
        "在同一个节点里挑姿态、脸模、服装三类白模参考图，各出一路 IMAGE。"
        "点类型展开图库、点缩略图选中；选「未使用」的一路输出阻塞。"
        "所有图片放在 ComfyUI/user/QQ_ComfyUI_Tools/GuliPoses/<类型>/img 下，升级插件不会丢。"
    )

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        return {
            "required": {
                "姿态": (_choices("pose"), {"default": _choices("pose")[0]}),
                "脸模": (_choices("face"), {"default": _choices("face")[0]}),
                "服装": (_choices("garment"), {"default": _choices("garment")[0]}),
            }
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs: Any) -> bool:
        # 选项随目录实时变化，旧工作流里可能存着已删掉的条目，不能硬校验。
        return True

    def pick(self, 姿态: str = UNUSED, 脸模: str = UNUSED, 服装: str = UNUSED):
        return (
            _pick_one("pose", 姿态),
            _pick_one("face", 脸模),
            _pick_one("garment", 服装),
        )


NODE_CLASS_MAPPINGS = {"QQGuliPosePicker": QQGuliPosePicker}
NODE_DISPLAY_NAME_MAPPINGS = {"QQGuliPosePicker": "QQ-白模参考"}
